//go:build ignore
package main
import("context";"encoding/json";"os";"fmt";"mime";"strings";"bufio";"sort";"github.com/Tencent/WeKnora/internal/application/service/file";"github.com/Tencent/WeKnora/internal/types/interfaces")
type physical struct{interfaces.FileService}
func(p *physical)SaveBytes(context.Context,[]byte,uint64,string,bool)(string,error){return "local://1/exports/oracle",nil}
type catalog struct{interfaces.ResourceCatalog;meta interfaces.ResourceRegistration}
func(c *catalog)Register(_ context.Context,_ uint64,_ string,m interfaces.ResourceRegistration)(string,error){c.meta=m;return "resource://AbCdEfGhIjKlMnOpQrStUv",nil}
func main(){snapshot:=[]map[string]string{};names:=map[string]bool{};for _,path:=range []string{"/usr/local/share/mime/globs2","/usr/share/mime/globs2","/etc/mime.types","/etc/apache2/mime.types","/etc/apache/mime.types","/etc/httpd/conf/mime.types"}{data,err:=os.ReadFile(path);if err!=nil{continue};snapshot=append(snapshot,map[string]string{"path":path,"content":string(data)});scanner:=bufio.NewScanner(strings.NewReader(string(data)));for scanner.Scan(){line:=scanner.Text();if strings.HasSuffix(path,"globs2"){p:=strings.Split(line,":");if len(p)>=3&&strings.HasPrefix(p[2],"*."){names["document"+p[2][1:]]=true}}else{p:=strings.Fields(line);if len(p)>1&&!strings.HasPrefix(p[0],"#"){for _,ext:=range p[1:]{if strings.HasPrefix(ext,"#"){break};names["document."+ext]=true}}}}}
for _,ext:=range strings.Fields("ai apk apng avif bin bmp com css csv doc docx ehtml eml eps exe flac gif gz htm html ico ics jfif jpeg jpg js json m4a mjs mp3 mp4 oga ogg ogv opus pdf pjp pjpeg png ppt pptx ps rdf rtf shtml svg text tif tiff txt vtt wasm wav webm webp xbl xbm xht xhtml xls xlsx xml xsl zip md markdown epub xmind mhtml"){names["document."+ext]=true;names["文档."+strings.ToUpper(ext)]=true}
for _,name:=range []string{"","/","////","file",".txt","nested/.txt","folder.txt/file","folder.txt/file/","folder.txt/","nested/a.png/","nested/../","nested/a.PNG","C:\\folder\\a.txt","C:\\folder\\a.TXT","a.tar.gz","a..json","a.","a.txt "," a.txt","a.txt?x","图.unknown","folder/图.İMG","folder//图.ǅat","a.svg#fragment","nested/a.JSON"}{names[name]=true}
keys:=[]string{};for name:=range names{keys=append(keys,name)};sort.Strings(keys);c:=&catalog{};svc:=file.NewResourceCatalogFileService(&physical{},c);rows:=[]map[string]interface{}{};for _,name:=range keys{_,err:=svc.SaveBytes(context.Background(),[]byte("golden"),1,name,false);if err!=nil{panic(err)};rows=append(rows,map[string]interface{}{"name":name,"mime":c.meta.MimeType,"kind":c.meta.Kind,"original_name":c.meta.OriginalName})}
params:=[]map[string]interface{}{};for i,input:=range []string{"text/test","text/test;charset=utf-16","text/test;charset=","text/test;charset=\"\"","TEXT/test","text/Test;FORMAT=Flowed","text/test;a=b;charset=utf-8","text/test;a=\"hello world\"","text/test;a=b;a=b","text/test;a=b;a=c","text/test;","text/test;;","text/test;a=\"C:\\foo\\bar\"","text/test;filename*=utf-8''%E5%9B%BE","text/test;filename*0=first;filename*1=second","text/test;filename*0*=utf-8''%E5%9B%BE;filename*1*=.txt","text/test;filename*=iso-8859-1''%A0","text/test;filename*=UTF-8'en'name%20a","bad","bad bad","text/test;a=\"a\\\"b\"","text/test;a=\"a\nb\"","text/test;a=\"\t\"","text/test;a=\"图\""}{ext:=fmt.Sprintf(".migration%d",i);err:=mime.AddExtensionType(ext,input);rows:=map[string]interface{}{"input":input,"valid":err==nil,"output":mime.TypeByExtension(ext)};params=append(params,rows)}
json.NewEncoder(os.Stdout).Encode(map[string]interface{}{"system_files":snapshot,"rows":rows,"parameters":params})}
